import { Field, FieldDescription, FieldError, FieldLabel } from "@/registry/erbium/ui/field";
import { Input as UIInput } from "@/registry/erbium/ui/input";

export default function FieldValidationAndErrorsExample() {
  return (
    <Field className="w-80" invalid>
      <FieldLabel>Email</FieldLabel>
      <UIInput placeholder="name@example.com" type="email" />
      <FieldDescription>We will use this to contact you.</FieldDescription>
      <FieldError match>Enter a valid email address.</FieldError>
    </Field>
  );
}
